messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: bfd/coff-rs6000.c
Line: 3295
Function: xcoff_reloc_type_br
Bug type: out-of-bounds-write
CWE: CWE-787
Explanation: A similar overflow-prone check uses section_offset + 4 <= input_section->size (line ~3285). If section_offset is large due to unsigned underflow, the addition can wrap, allowing the check to pass. The code then writes back to the buffer at ptr = contents + section_offset with bfd_put_32, leading to an out-of-bounds write when the relocation targets a defined absolute symbol.

Source context:
```c
     3255:   if (stub_type != xcoff_stub_none)
     3256:     {
     3257:       asection *stub_csect;
     3258: 
     3259:       stub_entry = bfd_xcoff_get_stub_entry (input_section, h, info);
     3260:       if (stub_entry == NULL)
     3261: 	{
     3262: 	  _bfd_error_handler (_("Unable to find the stub entry targeting %s"),
     3263: 			      h->root.root.string);
     3264: 	  bfd_set_error (bfd_error_bad_value);
     3265: 	  return false;
     3266: 	}
     3267: 
     3268:       stub_csect = stub_entry->hcsect->root.u.def.section;
     3269:       val = (stub_entry->stub_offset
     3270: 	     + stub_csect->output_section->vma
     3271: 	     + stub_csect->output_offset);
     3272:     }
     3273: 
     3274:   /* The original PC-relative relocation is biased by -r_vaddr, so adding
     3275:      the value below will give the absolute target address.  */
     3276:   *relocation = val + addend + rel->r_vaddr;
     3277: 
     3278:   howto->src_mask &= ~3;
     3279:   howto->dst_mask = howto->src_mask;
     3280: 
     3281:   if (h != NULL
     3282:       && (h->root.type == bfd_link_hash_defined
     3283: 	  || h->root.type == bfd_link_hash_defweak)
     3284:       && bfd_is_abs_section (h->root.u.def.section)
     3285:       && section_offset + 4 <= input_section->size)
     3286:     {
     3287:       bfd_byte *ptr;
     3288:       bfd_vma insn;
     3289: 
     3290:       /* Turn the relative branch into an absolute one by setting the
     3291: 	 AA bit.  */
     3292:       ptr = contents + section_offset;
     3293:       insn = bfd_get_32 (input_bfd, ptr);
     3294:       insn |= 2;
>>>  3295:       bfd_put_32 (input_bfd, insn, ptr);
     3296: 
     3297:       /* Make the howto absolute too.  */
     3298:       howto->pc_relative = false;
     3299:       howto->complain_on_overflow = complain_overflow_bitfield;
     3300:     }
     3301:   else
     3302:     {
     3303:       /* Use a PC-relative howto and subtract the instruction's address
     3304: 	 from the target address we calculated above.  */
     3305:       howto->pc_relative = true;
     3306:       *relocation -= (input_section->output_section->vma
     3307: 		      + input_section->output_offset
     3308: 		      + section_offset);
     3309:     }
     3310:   return true;
     3311: }
     3312: 
     3313: bool
     3314: xcoff_reloc_type_crel (bfd *input_bfd ATTRIBUTE_UNUSED,
     3315: 		       asection *input_section,
     3316: 		       bfd *output_bfd ATTRIBUTE_UNUSED,
     3317: 		       struct internal_reloc *rel ATTRIBUTE_UNUSED,
     3318: 		       struct internal_syment *sym ATTRIBUTE_UNUSED,
     3319: 		       struct reloc_howto_struct *howto,
     3320: 		       bfd_vma val ATTRIBUTE_UNUSED,
     3321: 		       bfd_vma addend,
     3322: 		       bfd_vma *relocation,
     3323: 		       bfd_byte *contents ATTRIBUTE_UNUSED,
     3324: 		       struct bfd_link_info *info ATTRIBUTE_UNUSED)
     3325: {
     3326:   howto->pc_relative = true;
     3327:   howto->src_mask &= ~3;
     3328:   howto->dst_mask = howto->src_mask;
     3329: 
     3330:   /* A PC relative reloc includes the section address.  */
     3331:   addend += input_section->vma;
     3332: 
     3333:   *relocation = val + addend;
     3334:   *relocation -= (input_section->output_section->vma
     3335: 		  + input_section->output_offset);
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/binutils_upstream reproducer.c -L/tmp/binutils_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/binutils_upstream
